-- The two affordability assessments, and their covering emails.
-- Generated by scripts/letters/seed-affordability.mjs --sql. Do not edit by hand; edit
-- affordability.mjs, run scripts/letters/build.mjs, and regenerate -- or the document in the
-- database stops matching the one in the repository.
-- Safe to run more than once. It removes nothing.
begin;
insert into public.message_templates
  (scope, kind, name, subject, format, body, seed_key, audience, active)
values
  ($q$collections$q$, $q$letter$q$, $q$Affordability assessment (individual)$q$, null, $q$document$q$, $q${"defaults":{"font":"\"Charter\", \"Bitstream Charter\", Georgia, serif","size":10.5,"colour":"#1f2937","lineHeight":1.45},"blocks":[{"kind":"table","borders":"none","widths":[28,72],"rows":[[{"spans":[{"text":"DATE","bold":true}]},{"spans":[{"text":"{{today}}"}]}],[{"spans":[{"text":"OUR REFERENCE","bold":true}]},{"spans":[{"text":"{{case_number}}"}]}],[{"spans":[{"text":"ACCOUNT","bold":true}]},{"spans":[{"text":"{{account_number}}"}]}],[{"spans":[{"text":"DELIVERY","bold":true}]},{"spans":[{"text":"By email, with notification by SMS"}]}]]},{"kind":"paragraph","spans":[{"text":"{{debtor_name}}"}]},{"kind":"paragraph","spans":[{"text":"Identity number: {{debtor_id_masked}}"}]},{"kind":"heading","level":1,"spans":[{"text":"AFFORDABILITY ASSESSMENT"}]},{"kind":"paragraph","spans":[{"text":"Financial information required before a payment arrangement can be put to the creditor"}]},{"kind":"paragraph","spans":[{"text":"Dear {{debtor_name}} — we act on behalf of {{client_name}}, the creditor. You have asked to pay the balance of {{balance}} over time. Before a proposal can be put to the creditor, we need the information set out below."}]},{"kind":"heading","level":2,"spans":[{"text":"WHAT TO SEND US"}],"numbered":true},{"kind":"paragraph","spans":[{"text":"Send these to us by email. Fill in the summary below, sign at the foot of this document, and attach the documents to your reply."}]},{"kind":"list","ordered":true,"keepTogether":true,"items":[[{"text":"Proof of income for the last three months: payslips if you are employed, or bank statements if you are not."}],[{"text":"Bank statements for your main account for the last three months."}],[{"text":"A copy of your identity document."}]]},{"kind":"heading","level":2,"spans":[{"text":"YOUR INCOME"}],"numbered":true},{"kind":"table","borders":"rows","headerRow":true,"widths":[62,38],"keepTogether":true,"rows":[[{"spans":[{"text":"INCOME","bold":true}]},{"spans":[{"text":"AMOUNT PER MONTH","bold":true}]}],[{"spans":[{"text":"Salary or wages, after deductions"}]},{"spans":[{"text":"R {{income_salary}}"}]}],[{"spans":[{"text":"Income from any other source"}]},{"spans":[{"text":"R {{income_other}}"}]}],[{"spans":[{"text":"Income of a spouse or partner who contributes"}]},{"spans":[{"text":"R {{income_partner}}"}]}],[{"spans":[{"text":"Total income","bold":true}]},{"spans":[{"text":"R {{income_total}}","bold":true}]}]]},{"kind":"heading","level":2,"spans":[{"text":"YOUR EXPENSES"}],"numbered":true},{"kind":"table","borders":"rows","headerRow":true,"widths":[62,38],"keepTogether":true,"rows":[[{"spans":[{"text":"EXPENSES","bold":true}]},{"spans":[{"text":"AMOUNT PER MONTH","bold":true}]}],[{"spans":[{"text":"Rent or bond"}]},{"spans":[{"text":"R {{expense_housing}}"}]}],[{"spans":[{"text":"Rates, water and electricity"}]},{"spans":[{"text":"R {{expense_utilities}}"}]}],[{"spans":[{"text":"Food and household"}]},{"spans":[{"text":"R {{expense_food}}"}]}],[{"spans":[{"text":"Transport, fuel or taxi fares"}]},{"spans":[{"text":"R {{expense_transport}}"}]}],[{"spans":[{"text":"School fees and childcare"}]},{"spans":[{"text":"R {{expense_school}}"}]}],[{"spans":[{"text":"Insurance and medical aid"}]},{"spans":[{"text":"R {{expense_medical}}"}]}],[{"spans":[{"text":"Other credit repayments"}]},{"spans":[{"text":"R {{expense_credit}}"}]}],[{"spans":[{"text":"Everything else"}]},{"spans":[{"text":"R {{expense_other}}"}]}],[{"spans":[{"text":"Total expenses","bold":true}]},{"spans":[{"text":"R {{expense_total}}","bold":true}]}]]},{"kind":"table","borders":"all","widths":[62,38],"keepTogether":true,"rows":[[{"spans":[{"text":"What is left each month","bold":true}]},{"spans":[{"text":"R {{affordability_left}}","bold":true}]}]]},{"kind":"heading","level":2,"spans":[{"text":"WHAT YOU CAN PAY"}],"numbered":true},{"kind":"table","borders":"rows","headerRow":true,"widths":[62,38],"keepTogether":true,"rows":[[{"spans":[{"text":"YOUR PROPOSAL","bold":true}]},{"spans":[{"text":"AMOUNT","bold":true}]}],[{"spans":[{"text":"Amount you propose to pay each time"}]},{"spans":[{"text":"R {{ptp_amount}}"}]}],[{"spans":[{"text":"How often it will be paid"}]},{"spans":[{"text":"{{ptp_frequency}}"}]}],[{"spans":[{"text":"The date of the first payment"}]},{"spans":[{"text":"{{ptp_date}}"}]}],[{"spans":[{"text":"Any lump sum you can pay now"}]},{"spans":[{"text":"R {{offer_lump_sum}}"}]}]]},{"kind":"heading","level":2,"spans":[{"text":"WHAT HAPPENS NEXT"}],"numbered":true},{"kind":"paragraph","spans":[{"text":"We use this information only to assess the proposal and to put it to the creditor, and we process it in accordance with the Protection of Personal Information Act 4 of 2013. A proposal cannot be considered until the information above has reached us, and the account continues on its normal course in the meantime."}]},{"kind":"paragraph","spans":[{"text":"Send the documents to {{agent_email}}, quoting reference {{case_number}}. We will revert as soon as the creditor has considered the proposal."}]},{"kind":"paragraph","spans":[{"text":"By signing below you confirm that the information given above is true and complete. This document is not an agreement to accept your proposal and it does not suspend the account."}]},{"kind":"spacer","mm":6},{"kind":"signature","widthMm":70,"signer":"debtor","spans":[{"text":"{{debtor_name}}"}]},{"kind":"paragraph","spans":[{"text":"{{firm_name}}, duly authorised agent of {{client_name}}"}]}]}$q$, $q$letter-affordability-individual$q$, $q$individual$q$, true),
  ($q$collections$q$, $q$email$q$, $q$Affordability assessment — covering email (individual)$q$, $q$Affordability assessment — account {{account_number}}$q$, $q$text$q$, $q$Dear {{debtor_name}}

Further to our discussion, attached is an affordability assessment for account {{account_number}}.

The balance is {{balance}}. Before a proposal can be put to the creditor we need to know what you can afford, which is what this form asks.

What to do:
Open it with the button below and fill in the figures. The totals work themselves out.
Say what you can pay and from when, then sign at the foot.
Reply to this email with the supporting documents listed in the form.

Filling this in does not suspend the account and it is not an agreement to accept the proposal. We will revert as soon as the creditor has considered it.

Kind regards
{{agent_name}}
{{firm_name}}
{{agent_phone}}$q$, $q$email-affordability-individual$q$, $q$individual$q$, true),
  ($q$collections$q$, $q$letter$q$, $q$Affordability assessment (company)$q$, null, $q$document$q$, $q${"defaults":{"font":"\"Charter\", \"Bitstream Charter\", Georgia, serif","size":10.5,"colour":"#1f2937","lineHeight":1.45},"blocks":[{"kind":"table","borders":"none","widths":[28,72],"rows":[[{"spans":[{"text":"DATE","bold":true}]},{"spans":[{"text":"{{today}}"}]}],[{"spans":[{"text":"OUR REFERENCE","bold":true}]},{"spans":[{"text":"{{case_number}}"}]}],[{"spans":[{"text":"ACCOUNT","bold":true}]},{"spans":[{"text":"{{account_number}}"}]}],[{"spans":[{"text":"DELIVERY","bold":true}]},{"spans":[{"text":"By email, with notification by SMS"}]}]]},{"kind":"paragraph","spans":[{"text":"{{debtor_name}}"}]},{"kind":"paragraph","spans":[{"text":"Registration number: {{debtor_reg_no}}"}]},{"kind":"heading","level":1,"spans":[{"text":"AFFORDABILITY ASSESSMENT"}]},{"kind":"paragraph","spans":[{"text":"Financial information required before a payment arrangement can be put to the creditor"}]},{"kind":"paragraph","spans":[{"text":"Dear Sirs / Madams — we act on behalf of {{client_name}}, the creditor. The company has asked to pay the balance of {{balance}} over time. Before a proposal can be put to the creditor, we need the information set out below."}]},{"kind":"heading","level":2,"spans":[{"text":"WHAT TO SEND US"}],"numbered":true},{"kind":"paragraph","spans":[{"text":"Send these to us by email. Fill in the proposal below, sign at the foot of this document, and attach the documents to your reply."}]},{"kind":"list","ordered":true,"keepTogether":true,"items":[[{"text":"The company’s latest management accounts, or its most recent annual financial statements if management accounts are not available."}],[{"text":"Bank statements for the company’s main account for the last three months."}],[{"text":"A debtors and creditors age analysis as at the date of this proposal."}],[{"text":"The name and capacity of the person signing on behalf of the company."}]]},{"kind":"heading","level":2,"spans":[{"text":"THE PROPOSAL"}],"numbered":true},{"kind":"table","borders":"rows","headerRow":true,"widths":[62,38],"keepTogether":true,"rows":[[{"spans":[{"text":"YOUR PROPOSAL","bold":true}]},{"spans":[{"text":"AMOUNT","bold":true}]}],[{"spans":[{"text":"Amount the company proposes to pay each time"}]},{"spans":[{"text":"R {{ptp_amount}}"}]}],[{"spans":[{"text":"How often it will be paid"}]},{"spans":[{"text":"{{ptp_frequency}}"}]}],[{"spans":[{"text":"The date of the first payment"}]},{"spans":[{"text":"{{ptp_date}}"}]}],[{"spans":[{"text":"Number of instalments proposed"}]},{"spans":[{"text":"{{offer_instalments}}"}]}],[{"spans":[{"text":"Any lump sum the company can pay now"}]},{"spans":[{"text":"R {{offer_lump_sum}}"}]}]]},{"kind":"heading","level":2,"spans":[{"text":"WHAT HAPPENS NEXT"}],"numbered":true},{"kind":"paragraph","spans":[{"text":"We use this information only to assess the proposal and to put it to the creditor, and we process it in accordance with the Protection of Personal Information Act 4 of 2013. A proposal cannot be considered until the information above has reached us, and the account continues on its normal course in the meantime."}]},{"kind":"paragraph","spans":[{"text":"Send the documents to {{agent_email}}, quoting reference {{case_number}}. We will revert as soon as the creditor has considered the proposal."}]},{"kind":"paragraph","spans":[{"text":"By signing below the company confirms that the information given above is true and complete. This document is not an agreement to accept the proposal and it does not suspend the account."}]},{"kind":"spacer","mm":6},{"kind":"signature","widthMm":70,"signer":"debtor","spans":[{"text":"for {{debtor_name}} ({{debtor_reg_no}}), duly authorised"}]},{"kind":"paragraph","spans":[{"text":"{{firm_name}}, duly authorised agent of {{client_name}}"}]}]}$q$, $q$letter-affordability-company$q$, $q$company$q$, true),
  ($q$collections$q$, $q$email$q$, $q$Affordability assessment — covering email (company)$q$, $q$Affordability assessment — account {{account_number}}$q$, $q$text$q$, $q$Dear {{debtor_name}}

Further to our discussion, attached is an affordability assessment for account {{account_number}}, for completion and signature by a duly authorised representative of {{debtor_name}}.

The balance is {{balance}}. Before a proposal can be put to the creditor we need to know what the company can afford, which is what this form asks.

What to do:
Open it with the button below and fill in the figures. The totals work themselves out.
Say what the company can pay and from when, then sign at the foot.
Reply to this email with the supporting documents listed in the form.

Filling this in does not suspend the account and it is not an agreement to accept the proposal. We will revert as soon as the creditor has considered it.

Kind regards
{{agent_name}}
{{firm_name}}
{{agent_phone}}$q$, $q$email-affordability-company$q$, $q$company$q$, true)
on conflict (seed_key) do update set
  scope = excluded.scope, kind = excluded.kind, name = excluded.name,
  subject = excluded.subject, format = excluded.format, body = excluded.body,
  audience = excluded.audience, active = excluded.active, updated_at = now();

-- AND THE COVERING EMAIL POSTS THE FORM. Set here rather than in the insert because a row
-- cannot point at an id it does not yet know. The pairing that matters is the AUDIENCE: a
-- covering note written to a person that posts the company's form would ask a pensioner for
-- management accounts.
update public.message_templates e
   set attachment_id = l.id
  from public.message_templates l
 where e.seed_key = 'email-affordability-individual'
   and l.seed_key = 'letter-affordability-individual';
update public.message_templates e
   set attachment_id = l.id
  from public.message_templates l
 where e.seed_key = 'email-affordability-company'
   and l.seed_key = 'letter-affordability-company';
commit;

-- Read back what landed. A truncated form is worse than a missing one: a missing template
-- cannot be chosen from a picker, and a truncated one can. Expect four rows, at these lengths:
--   5435 chars  Affordability assessment (individual)
--   704 chars  Affordability assessment — covering email (individual)
--   3746 chars  Affordability assessment (company)
--   805 chars  Affordability assessment — covering email (company)
select name, length(body) as chars from public.message_templates
 where seed_key like '%affordability%' order by name;
